CREATE TABLE IF NOT EXISTS w_migrations (version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS w_tiers (id INTEGER PRIMARY KEY AUTOINCREMENT,name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS w_users (id INTEGER PRIMARY KEY AUTOINCREMENT,email VARCHAR(254) NOT NULL UNIQUE,password VARCHAR(200) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'customer',status VARCHAR(30) NOT NULL DEFAULT 'pending',tier_id INTEGER DEFAULT 1,business VARCHAR(160) NOT NULL,contact VARCHAR(100) NOT NULL,phone VARCHAR(20) NOT NULL,business_type VARCHAR(60) NOT NULL,city VARCHAR(100) NOT NULL,state VARCHAR(100) NOT NULL,pincode VARCHAR(6) NOT NULL,address TEXT NOT NULL,gstin VARCHAR(15) NOT NULL DEFAULT '',notes TEXT,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(tier_id) REFERENCES w_tiers(id));
CREATE TABLE IF NOT EXISTS w_sessions (id VARCHAR(64) PRIMARY KEY,user_id INTEGER NOT NULL,expires BIGINT NOT NULL,FOREIGN KEY(user_id) REFERENCES w_users(id));
CREATE TABLE IF NOT EXISTS w_categories (id INTEGER PRIMARY KEY AUTOINCREMENT,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS w_products (id INTEGER PRIMARY KEY AUTOINCREMENT,name VARCHAR(160) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,sku VARCHAR(80) NOT NULL UNIQUE,category_id INTEGER NOT NULL,description TEXT,unit VARCHAR(20) NOT NULL DEFAULT 'pieces',price INTEGER DEFAULT NULL,cost INTEGER DEFAULT NULL,moq INTEGER NOT NULL DEFAULT 1,step INTEGER NOT NULL DEFAULT 1,tax INTEGER NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0,reserved INTEGER NOT NULL DEFAULT 0,threshold INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,featured INTEGER NOT NULL DEFAULT 1,image TEXT,variant VARCHAR(160) NOT NULL DEFAULT '',material VARCHAR(100) NOT NULL DEFAULT '',FOREIGN KEY(category_id) REFERENCES w_categories(id),CHECK(stock>=0),CHECK(reserved>=0),CHECK(stock>=reserved),CHECK(price IS NULL OR price>=0),CHECK(moq>0),CHECK(step>0));
CREATE TABLE IF NOT EXISTS w_prices (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,tier_id INTEGER,user_id INTEGER,min_qty INTEGER NOT NULL DEFAULT 1,price INTEGER NOT NULL,FOREIGN KEY(product_id) REFERENCES w_products(id),FOREIGN KEY(tier_id) REFERENCES w_tiers(id),FOREIGN KEY(user_id) REFERENCES w_users(id),CHECK(price>=0),CHECK(min_qty>0));
CREATE TABLE IF NOT EXISTS w_cart (user_id INTEGER NOT NULL,product_id INTEGER NOT NULL,qty INTEGER NOT NULL,PRIMARY KEY(user_id,product_id),FOREIGN KEY(user_id) REFERENCES w_users(id),FOREIGN KEY(product_id) REFERENCES w_products(id),CHECK(qty>0));
CREATE TABLE IF NOT EXISTS w_saved (user_id INTEGER NOT NULL,product_id INTEGER NOT NULL,PRIMARY KEY(user_id,product_id),FOREIGN KEY(user_id) REFERENCES w_users(id),FOREIGN KEY(product_id) REFERENCES w_products(id));
CREATE TABLE IF NOT EXISTS w_addresses (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,label VARCHAR(100),address TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES w_users(id));
CREATE TABLE IF NOT EXISTS w_orders (id INTEGER PRIMARY KEY AUTOINCREMENT,reference VARCHAR(60) NOT NULL UNIQUE,user_id INTEGER NOT NULL,status VARCHAR(60) NOT NULL DEFAULT 'Request Received',subtotal INTEGER NOT NULL,tax INTEGER NOT NULL,shipping INTEGER,discount INTEGER NOT NULL DEFAULT 0,total INTEGER,paid INTEGER NOT NULL DEFAULT 0,reservation INTEGER NOT NULL DEFAULT 0,address TEXT NOT NULL,notes TEXT,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES w_users(id));
CREATE TABLE IF NOT EXISTS w_order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,product_id INTEGER NOT NULL,name VARCHAR(160) NOT NULL,sku VARCHAR(80) NOT NULL,variant VARCHAR(160) NOT NULL,unit VARCHAR(20) NOT NULL,qty INTEGER NOT NULL,price INTEGER NOT NULL,tax INTEGER NOT NULL,FOREIGN KEY(order_id) REFERENCES w_orders(id),FOREIGN KEY(product_id) REFERENCES w_products(id));
CREATE TABLE IF NOT EXISTS w_history (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,actor_id INTEGER NOT NULL,event TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(order_id) REFERENCES w_orders(id),FOREIGN KEY(actor_id) REFERENCES w_users(id));
CREATE TABLE IF NOT EXISTS w_payments (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL,amount INTEGER NOT NULL,method VARCHAR(30) NOT NULL,reference VARCHAR(160) NOT NULL UNIQUE,payment_date VARCHAR(30) NOT NULL,verified_by INTEGER NOT NULL,verified_at VARCHAR(30) NOT NULL,notes TEXT,FOREIGN KEY(order_id) REFERENCES w_orders(id),FOREIGN KEY(verified_by) REFERENCES w_users(id));
CREATE TABLE IF NOT EXISTS w_shipping (order_id INTEGER PRIMARY KEY,courier VARCHAR(100),tracking VARCHAR(160),link TEXT,dispatched_at VARCHAR(30),estimated_date VARCHAR(30),FOREIGN KEY(order_id) REFERENCES w_orders(id));
CREATE TABLE IF NOT EXISTS w_movements (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL,actor_id INTEGER NOT NULL,delta INTEGER NOT NULL,reason TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(product_id) REFERENCES w_products(id),FOREIGN KEY(actor_id) REFERENCES w_users(id));
CREATE TABLE IF NOT EXISTS w_audit (id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id INTEGER NOT NULL,event TEXT NOT NULL,created_at VARCHAR(30) NOT NULL,FOREIGN KEY(actor_id) REFERENCES w_users(id));
CREATE TABLE IF NOT EXISTS w_settings (id INTEGER PRIMARY KEY,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS w_images (id INTEGER PRIMARY KEY AUTOINCREMENT,mime VARCHAR(40) NOT NULL,image_data LONGTEXT NOT NULL);
